// Writing exercise data: 3 levels × 10 lessons × 10 questions
// ─────────────────────────────────────────────
// DATA MODEL
// ─────────────────────────────────────────────
class WritingQuestion {
  final String sentence; // Full correct sentence
  final String hint;     // Translation hint
  final List<String> keywords; // Key words to highlight in correction

  const WritingQuestion({
    required this.sentence,
    required this.hint,
    this.keywords = const [],
  });
}

class WritingLesson {
  final int lessonNumber;
  final String title;
  final List<WritingQuestion> questions;

  const WritingLesson({
    required this.lessonNumber,
    required this.title,
    required this.questions,
  });
}

