  WritingLesson(lessonNumber: 5, title: 'Câu phức & Mệnh đề quan hệ', questions: [
    WritingQuestion(sentence: 'The scientist whose research led to the breakthrough received the Nobel Prize.', hint: 'Nhà khoa học mà nghiên cứu dẫn đến bước đột phá đã nhận giải Nobel.', keywords: ['whose', 'breakthrough', 'Nobel']),
    WritingQuestion(sentence: 'The city where I grew up has changed beyond recognition.', hint: 'Thành phố nơi tôi lớn lên đã thay đổi đến mức không còn nhận ra được.', keywords: ['where', 'grew up', 'recognition']),
    WritingQuestion(sentence: 'Having completed the project, she turned her attention to a new challenge.', hint: 'Sau khi hoàn thành dự án, cô ấy chuyển sang một thách thức mới.', keywords: ['Having completed', 'attention', 'challenge']),
    WritingQuestion(sentence: 'The report, which was published last year, revealed alarming environmental data.', hint: 'Báo cáo, được công bố năm ngoái, tiết lộ dữ liệu môi trường đáng báo động.', keywords: ['which', 'published', 'alarming']),
    WritingQuestion(sentence: 'Not until she graduated did she fully appreciate the value of her education.', hint: 'Mãi đến khi tốt nghiệp, cô ấy mới thực sự trân trọng giá trị của nền giáo dục.', keywords: ['Not until', 'graduated', 'appreciate']),
    WritingQuestion(sentence: 'The technology, though initially expensive, proved to be remarkably cost-effective.', hint: 'Công nghệ này, dù ban đầu đắt đỏ, đã chứng tỏ hiệu quả chi phí đáng kể.', keywords: ['though', 'initially', 'cost-effective']),
    WritingQuestion(sentence: 'Whatever the outcome, the lessons learned from this experience will be invaluable.', hint: 'Dù kết quả thế nào, những bài học từ trải nghiệm này sẽ vô giá.', keywords: ['Whatever', 'outcome', 'invaluable']),
    WritingQuestion(sentence: 'The more companies invest in employee training, the more productive the workforce becomes.', hint: 'Các công ty đầu tư vào đào tạo nhân viên càng nhiều, lực lượng lao động càng năng suất.', keywords: ['more', 'invest', 'productive']),
    WritingQuestion(sentence: 'It is widely acknowledged that lifelong learning is the key to professional success.', hint: 'Được công nhận rộng rãi rằng học tập suốt đời là chìa khóa để thành công nghề nghiệp.', keywords: ['acknowledged', 'lifelong learning', 'professional']),
    WritingQuestion(sentence: 'The challenges posed by rapid urbanization are manifold and require urgent policy intervention.', hint: 'Những thách thức do đô thị hóa nhanh chóng là đa dạng và cần can thiệp chính sách khẩn cấp.', keywords: ['posed', 'manifold', 'intervention']),
  ]),
  WritingLesson(lessonNumber: 6, title: 'Mô tả xu hướng & Thống kê', questions: [
    WritingQuestion(sentence: 'The statistics indicate a marked improvement in literacy rates over the past twenty years.', hint: 'Thống kê cho thấy sự cải thiện rõ rệt trong tỷ lệ biết đọc biết viết trong 20 năm qua.', keywords: ['statistics', 'marked improvement', 'literacy']),
    WritingQuestion(sentence: 'There has been a precipitous decline in biodiversity due to human activity.', hint: 'Đã có sự sụt giảm mạnh về đa dạng sinh học do hoạt động của con người.', keywords: ['precipitous', 'decline', 'biodiversity']),
    WritingQuestion(sentence: 'The data unequivocally demonstrates that physical activity reduces the risk of chronic disease.', hint: 'Dữ liệu cho thấy rõ ràng rằng hoạt động thể chất giảm nguy cơ mắc bệnh mãn tính.', keywords: ['unequivocally', 'demonstrates', 'chronic disease']),
    WritingQuestion(sentence: 'Economic growth has been unevenly distributed, benefiting primarily the wealthiest segments.', hint: 'Tăng trưởng kinh tế phân bố không đều, chủ yếu mang lại lợi ích cho các bộ phận giàu có nhất.', keywords: ['unevenly', 'distributed', 'wealthiest']),
    WritingQuestion(sentence: 'The mortality rate associated with cardiovascular disease has decreased substantially.', hint: 'Tỷ lệ tử vong liên quan đến bệnh tim mạch đã giảm đáng kể.', keywords: ['mortality', 'cardiovascular', 'substantially']),
    WritingQuestion(sentence: 'Contrary to popular belief, crime rates in most urban areas have declined significantly.', hint: 'Trái với quan niệm phổ biến, tỷ lệ tội phạm ở hầu hết các khu vực thành thị đã giảm đáng kể.', keywords: ['Contrary', 'popular belief', 'declined']),
    WritingQuestion(sentence: 'The correlation between socioeconomic status and academic performance is well-documented.', hint: 'Mối tương quan giữa tình trạng kinh tế xã hội và thành tích học tập được ghi nhận rõ ràng.', keywords: ['correlation', 'socioeconomic', 'well-documented']),
    WritingQuestion(sentence: 'Renewable energy capacity has grown exponentially, surpassing fossil fuel generation in many regions.', hint: 'Công suất năng lượng tái tạo đã tăng theo cấp số nhân, vượt qua sản xuất nhiên liệu hóa thạch ở nhiều khu vực.', keywords: ['exponentially', 'surpassing', 'fossil fuel']),
    WritingQuestion(sentence: 'The longitudinal study followed participants over a period of thirty years.', hint: 'Nghiên cứu theo dọc theo dõi những người tham gia trong khoảng thời gian 30 năm.', keywords: ['longitudinal', 'followed', 'participants']),
    WritingQuestion(sentence: 'Preliminary findings suggest a strong inverse relationship between stress and immunity.', hint: 'Phát hiện sơ bộ gợi ý mối quan hệ nghịch chiều mạnh mẽ giữa stress và miễn dịch.', keywords: ['Preliminary', 'inverse relationship', 'immunity']),
  ]),
  WritingLesson(lessonNumber: 7, title: 'Nguyên nhân & Hệ quả', questions: [
    WritingQuestion(sentence: 'Deforestation has precipitated a dramatic reduction in habitat for indigenous species.', hint: 'Nạn phá rừng đã gây ra sự giảm mạnh về môi trường sống cho các loài bản địa.', keywords: ['Deforestation', 'precipitated', 'indigenous']),
    WritingQuestion(sentence: 'The economic recession resulted in unprecedented levels of unemployment.', hint: 'Suy thoái kinh tế dẫn đến mức thất nghiệp chưa từng có.', keywords: ['recession', 'resulted', 'unprecedented']),
    WritingQuestion(sentence: 'Exposure to excessive screen time contributes to deteriorating eyesight in young people.', hint: 'Tiếp xúc quá nhiều với màn hình góp phần làm suy giảm thị lực ở người trẻ.', keywords: ['Exposure', 'contributes', 'deteriorating']),
    WritingQuestion(sentence: 'Political instability often leads to economic stagnation and social unrest.', hint: 'Bất ổn chính trị thường dẫn đến trì trệ kinh tế và bất ổn xã hội.', keywords: ['instability', 'stagnation', 'unrest']),
    WritingQuestion(sentence: 'Consequently, the lack of investment in education perpetuates the cycle of poverty.', hint: 'Do đó, sự thiếu đầu tư vào giáo dục duy trì vòng luẩn quẩn của nghèo đói.', keywords: ['Consequently', 'perpetuates', 'poverty']),
    WritingQuestion(sentence: 'The advent of the internet has fundamentally altered patterns of human interaction.', hint: 'Sự xuất hiện của internet đã thay đổi căn bản các mẫu tương tác của con người.', keywords: ['advent', 'fundamentally', 'altered']),
    WritingQuestion(sentence: 'As a direct consequence, migration patterns have shifted dramatically over recent decades.', hint: 'Hậu quả trực tiếp, các mẫu di cư đã thay đổi đáng kể trong những thập kỷ gần đây.', keywords: ['direct consequence', 'migration', 'dramatically']),
    WritingQuestion(sentence: 'Prolonged exposure to air pollution can trigger serious respiratory and cardiovascular conditions.', hint: 'Tiếp xúc lâu dài với ô nhiễm không khí có thể gây ra các bệnh hô hấp và tim mạch nghiêm trọng.', keywords: ['Prolonged', 'trigger', 'respiratory']),
    WritingQuestion(sentence: 'The proliferation of misinformation has eroded public trust in mainstream media.', hint: 'Sự lan rộng của thông tin sai lệch đã làm xói mòn niềm tin của công chúng vào truyền thông chính thống.', keywords: ['proliferation', 'misinformation', 'eroded']),
    WritingQuestion(sentence: 'Technological unemployment stems from automation displacing workers across multiple sectors.', hint: 'Thất nghiệp do công nghệ bắt nguồn từ tự động hóa thay thế công nhân trong nhiều lĩnh vực.', keywords: ['Technological', 'stems', 'displacing']),
  ]),
  WritingLesson(lessonNumber: 8, title: 'Nghị luận & Phản biện', questions: [
    WritingQuestion(sentence: 'While this position has merit, it fails to account for the complexity of the issue.', hint: 'Mặc dù lập trường này có giá trị, nhưng nó không tính đến sự phức tạp của vấn đề.', keywords: ['merit', 'fails', 'complexity']),
    WritingQuestion(sentence: 'The argument that technology creates more jobs than it destroys is fundamentally flawed.', hint: 'Lập luận rằng công nghệ tạo ra nhiều việc làm hơn là nó hủy phá về cơ bản là sai.', keywords: ['argument', 'fundamentally flawed']),
    WritingQuestion(sentence: 'Counterintuitively, stricter gun laws may not necessarily reduce overall violence rates.', hint: 'Một cách trái với trực giác, luật súng nghiêm ngặt hơn có thể không nhất thiết giảm tỷ lệ bạo lực tổng thể.', keywords: ['Counterintuitively', 'stricter', 'necessarily']),
    WritingQuestion(sentence: 'Opponents of free trade argue that it compromises national sovereignty and worker rights.', hint: 'Những người phản đối thương mại tự do lập luận rằng nó xâm phạm chủ quyền quốc gia và quyền công nhân.', keywords: ['Opponents', 'compromises', 'sovereignty']),
    WritingQuestion(sentence: 'This objection, while understandable, overlooks the broader macroeconomic benefits.', hint: 'Sự phản đối này, mặc dù có thể hiểu được, bỏ qua những lợi ích kinh tế vĩ mô rộng lớn hơn.', keywords: ['objection', 'understandable', 'macroeconomic']),
    WritingQuestion(sentence: 'The counterargument rests on a fundamental misrepresentation of the empirical data.', hint: 'Lập luận phản biện dựa trên sự bóp méo cơ bản của dữ liệu thực nghiệm.', keywords: ['counterargument', 'misrepresentation', 'empirical']),
    WritingQuestion(sentence: 'It is disingenuous to attribute the rise in inequality solely to technological change.', hint: 'Thật không thành thật khi quy kết sự gia tăng bất bình đẳng chỉ cho sự thay đổi công nghệ.', keywords: ['disingenuous', 'attribute', 'solely']),
    WritingQuestion(sentence: 'The polarization of political discourse undermines the foundations of democratic deliberation.', hint: 'Sự phân cực của diễn ngôn chính trị làm suy yếu nền tảng của sự thảo luận dân chủ.', keywords: ['polarization', 'undermines', 'deliberation']),
    WritingQuestion(sentence: 'Admittedly, there are instances where market mechanisms fail to produce equitable outcomes.', hint: 'Phải thừa nhận rằng có những trường hợp cơ chế thị trường không tạo ra kết quả công bằng.', keywords: ['Admittedly', 'mechanisms', 'equitable']),
    WritingQuestion(sentence: 'The proposition that economic growth invariably benefits all strata of society is empirically untenable.', hint: 'Đề xuất rằng tăng trưởng kinh tế luôn có lợi cho mọi tầng lớp xã hội là không thể chứng minh về mặt thực nghiệm.', keywords: ['proposition', 'invariably', 'untenable']),
  ]),
  WritingLesson(lessonNumber: 9, title: 'Lập luận & Kết luận', questions: [
    WritingQuestion(sentence: 'In light of the foregoing evidence, it is reasonable to conclude that action is required.', hint: 'Dưới ánh sáng của bằng chứng nêu trên, có thể kết luận một cách hợp lý rằng cần phải hành động.', keywords: ['In light of', 'foregoing', 'conclude']),
    WritingQuestion(sentence: 'Taking all factors into consideration, the proposed solution is both pragmatic and sustainable.', hint: 'Xem xét tất cả các yếu tố, giải pháp được đề xuất vừa thực tế vừa bền vững.', keywords: ['Taking', 'pragmatic', 'sustainable']),
    WritingQuestion(sentence: 'The cumulative weight of evidence overwhelmingly supports the need for systemic reform.', hint: 'Trọng lượng tích lũy của bằng chứng áp đảo ủng hộ sự cần thiết phải cải cách hệ thống.', keywords: ['cumulative', 'overwhelmingly', 'systemic reform']),
    WritingQuestion(sentence: 'Ultimately, individual behavioral change must be complemented by structural policy reforms.', hint: 'Cuối cùng, sự thay đổi hành vi cá nhân phải được bổ sung bởi các cải cách chính sách cấu trúc.', keywords: ['Ultimately', 'complemented', 'structural']),
    WritingQuestion(sentence: 'It would be precipitous to draw firm conclusions based on such limited data.', hint: 'Sẽ là vội vàng khi đưa ra kết luận chắc chắn dựa trên dữ liệu hạn chế như vậy.', keywords: ['precipitous', 'firm conclusions', 'limited data']),
    WritingQuestion(sentence: 'The synthesis of these perspectives offers a more nuanced understanding of the phenomenon.', hint: 'Sự tổng hợp các quan điểm này cung cấp sự hiểu biết tinh tế hơn về hiện tượng này.', keywords: ['synthesis', 'nuanced', 'phenomenon']),
    WritingQuestion(sentence: 'Future research should investigate the long-term ramifications of these policy interventions.', hint: 'Nghiên cứu trong tương lai nên điều tra những hậu quả lâu dài của các can thiệp chính sách này.', keywords: ['Future research', 'long-term', 'ramifications']),
    WritingQuestion(sentence: 'Without substantial investment in infrastructure, economic progress will remain elusive.', hint: 'Nếu không có đầu tư đáng kể vào cơ sở hạ tầng, tiến bộ kinh tế sẽ còn khó nắm bắt.', keywords: ['substantial', 'infrastructure', 'elusive']),
    WritingQuestion(sentence: 'The imperative to act on climate change transcends national borders and political ideologies.', hint: 'Sự cần thiết phải hành động về biến đổi khí hậu vượt qua biên giới quốc gia và các hệ tư tưởng chính trị.', keywords: ['imperative', 'transcends', 'ideologies']),
    WritingQuestion(sentence: 'In conclusion, a holistic and collaborative approach is indispensable for resolving this crisis.', hint: 'Kết luận, cách tiếp cận toàn diện và hợp tác là không thể thiếu để giải quyết cuộc khủng hoảng này.', keywords: ['holistic', 'collaborative', 'indispensable']),
  ]),
  WritingLesson(lessonNumber: 10, title: 'Viết sáng tạo & Phong cách', questions: [
    WritingQuestion(sentence: 'The labyrinthine corridors of bureaucracy have long frustrated ambitious reformers.', hint: 'Những hành lang mê cung của bộ máy quan liêu từ lâu đã làm thất vọng những nhà cải cách đầy tham vọng.', keywords: ['labyrinthine', 'bureaucracy', 'reformers']),
    WritingQuestion(sentence: 'Her eloquent prose captivated readers across generations and cultural divides.', hint: 'Văn xuôi hùng hồn của cô ấy thu hút độc giả qua các thế hệ và ranh giới văn hóa.', keywords: ['eloquent', 'captivated', 'divides']),
    WritingQuestion(sentence: 'The cacophony of competing voices makes rational discourse nearly impossible.', hint: 'Sự ồn ào của những tiếng nói cạnh tranh khiến diễn ngôn hợp lý gần như không thể.', keywords: ['cacophony', 'rational discourse']),
    WritingQuestion(sentence: 'Technology has become an inextricable part of the human condition in the modern era.', hint: 'Công nghệ đã trở thành một phần không thể tách rời của thân phận con người trong thời đại hiện đại.', keywords: ['inextricable', 'human condition']),
    WritingQuestion(sentence: 'The ephemeral nature of digital content challenges traditional notions of cultural preservation.', hint: 'Tính thoáng qua của nội dung kỹ thuật số thách thức các khái niệm truyền thống về bảo tồn văn hóa.', keywords: ['ephemeral', 'notions', 'preservation']),
    WritingQuestion(sentence: 'Amidst the turbulence of geopolitical change, cultural identity serves as an anchor.', hint: 'Giữa sự hỗn loạn của biến đổi địa chính trị, bản sắc văn hóa đóng vai trò như một mỏ neo.', keywords: ['turbulence', 'geopolitical', 'anchor']),
    WritingQuestion(sentence: 'The dichotomy between tradition and modernity lies at the heart of contemporary cultural debate.', hint: 'Sự đối lập giữa truyền thống và hiện đại nằm ở trung tâm của cuộc tranh luận văn hóa đương đại.', keywords: ['dichotomy', 'lies at the heart']),
    WritingQuestion(sentence: 'Paradoxically, the age of unprecedented connectivity has produced profound feelings of isolation.', hint: 'Một cách nghịch lý, thời đại kết nối chưa từng có đã tạo ra cảm giác cô đơn sâu sắc.', keywords: ['Paradoxically', 'unprecedented', 'isolation']),
    WritingQuestion(sentence: 'The vicissitudes of fortune are inextricably linked to the inequities of birth and circumstance.', hint: 'Những biến động của vận mệnh gắn liền không thể tách rời với sự bất bình đẳng của sinh phận và hoàn cảnh.', keywords: ['vicissitudes', 'inextricably', 'inequities']),
    WritingQuestion(sentence: 'In the final analysis, it is human ingenuity and compassion that will determine our collective fate.', hint: 'Phân tích cuối cùng, chính sự khéo léo và lòng trắc ẩn của con người sẽ quyết định số phận chung của chúng ta.', keywords: ['ingenuity', 'compassion', 'collective fate']),
  ]),
];
